CREATE TABLE IF NOT EXISTS project_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_name TEXT NOT NULL,
    event_date DATE NOT NULL,
    payload JSONB NOT NULL,
    estimate NUMERIC(10, 2),
    archived BOOLEAN NOT NULL DEFAULT FALSE
);

INSERT INTO project_events (id, project_name, event_date, payload, estimate, archived)
SELECT n, 'Проект ' || n, DATE '2025-01-01' + n,
       jsonb_build_object('kind', CASE WHEN n % 2 = 0 THEN 'release' ELSE 'task' END,
                          'labels', jsonb_build_array('demo', 'fixture', n),
                          'enabled', n % 3 <> 0),
       n * 125.50, n % 5 = 0
FROM generate_series(1, 12) AS series(n)
WHERE NOT EXISTS (SELECT 1 FROM project_events WHERE id = n);

SELECT setval(
    pg_get_serial_sequence('project_events', 'id'),
    GREATEST(COALESCE((SELECT MAX(id) FROM project_events), 1), 1),
    EXISTS (SELECT 1 FROM project_events)
);
